  "Codan": { about: ["Codan is an Australian technology company based in Adelaide. It makes metal detectors for gold prospecting and demining under the Minelab brand, high-frequency radio equipment and communications systems for defence and humanitarian customers, and mining technology.", "It employs electronics, software and mechanical engineers, technicians and assemblers, product and manufacturing staff, sales and customer support staff, supply chain and finance staff, and corporate staff. Many roles are at its Adelaide design and manufacturing base, and engineering graduate roles are advertised from time to time."], spec: ["Metal detection", "Radio communications", "Electronics engineering", "Manufacturing", "Defence and mining technology"], hq: "Adelaide, SA", roles: ["Electronics engineer", "Software engineer", "Technician", "Manufacturing", "Sales"] },
  "Ocius Technology": { about: ["Ocius Technology is a Sydney-based Australian company that builds uncrewed surface vessels, including the solar- and wave-powered Bluebottle, for defence, maritime surveillance and ocean monitoring. It is a small technology company working with defence and commercial customers.", "It employs marine and mechanical engineers, software and systems engineers, technicians and operations staff, and business and administration staff. It suits people with engineering, maritime or robotics backgrounds who want to work in a small, fast-moving company."], spec: ["Uncrewed vessels", "Maritime surveillance", "Marine engineering", "Software and systems", "Defence technology"], hq: "Sydney, NSW", roles: ["Marine engineer", "Software engineer", "Systems engineer", "Technician", "Operations"] },
