  "Quickstep Holdings": { about: ["Quickstep Holdings is an Australian manufacturer of advanced composite parts, mainly carbon fibre components for aircraft and defence customers. It makes parts for military aircraft and runs processes that take composite materials from design through to finished components.", "It employs composite technicians and machine operators, manufacturing and process engineers, quality and inspection staff, supply chain and logistics staff, and corporate staff. Roles suit people with manufacturing, aerospace or trade backgrounds, and apprenticeships are a common way in."], spec: ["Composites manufacturing", "Aerospace components", "Quality and inspection", "Process engineering", "Defence supply chain"], roles: ["Composite technician", "Process engineer", "Machine operator", "Quality inspector", "Supply chain"] },

